// Title: Create a PDF from a worksheet using a custom print area and ensure only that range is exported with Aspose.Cells for .NET
// Common Searches: how to set a custom print area in Aspose.Cells before exporting to PDF in C# | verify that PDF generated by Aspose.Cells contains only the cells from a defined print range | Aspose.Cells C# export specific worksheet range to PDF using PdfSaveOptions | retrieve cell values from a print area in Aspose.Cells for PDF validation | save Excel worksheet as PDF with one page per sheet and custom print area Aspose.Cells
// Tags: print area definition Aspose.Cells | range-based PDF export Aspose.Cells | PdfSaveOptions OnePagePerSheet usage | PDF content verification against Excel range C# | cell value extraction from defined range Aspose.Cells | C# generate PDF from worksheet subset

using System;
using System.Collections.Generic;
using System.IO;
using Aspose.Cells;

// The example loads an Excel workbook, defines a custom print area (e.g., A1:C10) on the first worksheet, and saves the sheet to PDF using PdfSaveOptions with OnePagePerSheet enabled. It then extracts the values from the specified range and prints them for manual verification, noting that full PDF text validation would require an additional PDF parsing library.
class PrintAreaPdfValidator
{
    static void Main()
    {
        try
        {
            const string inputPath = "input.xlsx";
            const string outputPdfPath = "output.pdf";

            // Verify that the input workbook exists
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Error: Input file '{inputPath}' not found.");
                return;
            }

            // Load the workbook
            Workbook workbook = new Workbook(inputPath);

            // Define the custom print area (example: A1:C10)
            string printArea = "A1:C10";
            Worksheet sheet = workbook.Worksheets[0];
            sheet.PageSetup.PrintArea = printArea;

            // Prepare PDF save options (print area will be respected automatically)
            PdfSaveOptions pdfOptions = new PdfSaveOptions
            {
                OnePagePerSheet = true
            };

            // Save the worksheet to PDF
            workbook.Save(outputPdfPath, pdfOptions);
            Console.WriteLine($"PDF saved to '{outputPdfPath}'.");

            // Collect expected cell values from the defined print area
            List<string> expectedValues = new List<string>();
            Aspose.Cells.Range range = sheet.Cells.CreateRange(printArea);
            foreach (Cell cell in range)
            {
                if (cell.Value != null)
                {
                    expectedValues.Add(cell.Value.ToString());
                }
            }

            // Output the expected values (for manual verification)
            Console.WriteLine("Expected values from the print area:");
            foreach (string val in expectedValues)
            {
                Console.WriteLine(val);
            }

            // Note: Full PDF text validation would require Aspose.Pdf or another PDF parsing library.
            // This example focuses on generating the PDF with the correct print area.
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An unexpected error occurred: {ex.Message}");
        }
    }
}
